def count(a, used, last, placed):
    if placed == len(a):
        return 1
    total = 0
    for i in range(len(a)):
        if used[i]:
            continue
        if i > 0 and a[i] == a[i - 1] and not used[i - 1]:
            continue
        if last < 0 or is_square(last + a[i]):
            used[i] = True
            total += count(a, used, a[i], placed + 1)
            used[i] = False
    return total

